// A stand-in for esbuild that moves lines: it drops blank lines and line comments, and strips `: type`
// annotations, as compilers reformat code. It leaves an inline source map, as esbuild does with sourcemap: 'inline'.
const BASE64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';

function vlq(value) {
  let rest = value < 0 ? (-value << 1) | 1 : value << 1;
  let out = '';
  do {
    let digit = rest & 31;
    rest >>>= 5;
    if (rest > 0) {
      digit |= 32;
    }
    out += BASE64[digit];
  } while (rest > 0);
  return out;
}

function transformSync(source, options) {
  const lines = source.split('\n');
  const kept = [];
  lines.forEach((line, index) => {
    if (line.trim() === '' || line.trim().startsWith('//')) {
      return;
    }
    kept.push({ text: line.replace(/([\w)])\s*:\s*(?:number|string|boolean)(?:\[\])?/g, '$1'), index });
  });
  // One segment per line, at its start: generated column 0 to the original line, column 0.
  let previous = 0;
  const mappings = kept
    .map(({ index }) => {
      const segment = `A${vlq(0)}${vlq(index - previous)}A`;
      previous = index;
      return segment;
    })
    .join(';');
  const map = { version: 3, sources: [options.sourcefile], names: [], mappings };
  const code = `${kept.map(({ text }) => text).join('\n')}\n//# sourceMappingURL=data:application/json;base64,${Buffer.from(JSON.stringify(map)).toString('base64')}\n`;
  return { code };
}

module.exports = { transformSync, version: '0.0.0-fake' };
